function adicionarNumFase(inputFC) {

  // 1. Verifica e lista as fases únicas ordenadas
  // Agregamos a coluna 'fase', pegamos os valores distintos e os ordenamos.
  var listaDeFases = inputFC.aggregate_array('fase').distinct().sort();

  // Se não houver dados, retorna o mesmo objeto sem erros
  if (!listaDeFases.isEmpty()) {

    // 2. Prepara o dicionário de mapeamento interno
